'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const state = new Map();

let time = 0;
let gap = 1;
let seenEvent = false;

for (let i = 1; i < input.length; i += 2) {
  const type = input[i];
  const value = Number(input[i + 1]);

  if (type === 'T') {
    gap = value;
    continue;
  }

  if (seenEvent) time += gap;
  seenEvent = true;
  gap = 1;

  if (!state.has(value)) {
    state.set(value, { total: 0, receivedAt: [] });
  }

  const friend = state.get(value);

  if (type === 'R') {
    friend.receivedAt.push(time);
  } else {
    const receivedTime = friend.receivedAt.shift();
    friend.total += time - receivedTime;
  }
}

const output = [...state.keys()]
  .sort((a, b) => a - b)
  .map(id => {
    const friend = state.get(id);
    return `${id} ${friend.receivedAt.length > 0 ? -1 : friend.total}`;
  });

console.log(output.join('\n'));
